import { gregorianToHijri } from "@/lib/hijri";

/**
 * Seasonal app icons (NF-2.23b). The art lives in `assets/images/app-icons/<id>/`
 * (generated by `scripts/generate-seasonal-icons.py`) and is compiled into the
 * binaries by `modules/munib-app-icon/app.plugin.js` — keep `APP_ICON_IDS` in step
 * with that plugin's `ALTERNATE_ICONS` (`icons.test.ts` checks it).
 */
export const APP_ICON_IDS = [
  "ramadan",
  "lastTen",
  "eidFitr",
  "hajj",
  "eidAdha",
  "newYear",
  "ashura",
] as const;

export type AppIconId = (typeof APP_ICON_IDS)[number];

/**
 * The persisted choice: follow the Islamic calendar, always the classic icon, or
 * one icon kept all year.
 */
export type AppIconPreference = "seasonal" | "classic" | AppIconId;

export const APP_ICON_PREFERENCES: readonly AppIconPreference[] = [
  "seasonal",
  "classic",
  ...APP_ICON_IDS,
];

export interface AppIconSeason {
  id: AppIconId;
  /** Hijri month, 1–12. */
  hijriMonth: number;
  fromDay: number;
  toDay: number;
  /** i18n key of the icon's name — reuses the seasonal banner / Eid labels. */
  labelKey: string;
}

/**
 * When each icon is shown in "seasonal" mode. The windows follow the home seasonal
 * banners (`lib/seasonal-themes.ts`) but are coarser on purpose: an icon change on
 * iOS always shows a system alert, so the short banner-only seasons (Arafah, the
 * 27th night) stay inside their surrounding icon season. The New Year icon covers
 * 1–8 Muharram so it isn't a one-day flash; Ashura (9–10, the Sunnah fast days)
 * follows with its own sober icon. No icon for Mawlid or Isra' (D75).
 */
export const APP_ICON_SEASONS: readonly AppIconSeason[] = [
  {
    id: "newYear",
    hijriMonth: 1,
    fromDay: 1,
    toDay: 8,
    labelKey: "seasonalTheme.newYearBannerTitle",
  },
  {
    id: "ashura",
    hijriMonth: 1,
    fromDay: 9,
    toDay: 10,
    labelKey: "seasonalTheme.ashuraBannerTitle",
  },
  { id: "ramadan", hijriMonth: 9, fromDay: 1, toDay: 20, labelKey: "seasonalTheme.ramadanEyebrow" },
  {
    id: "lastTen",
    hijriMonth: 9,
    fromDay: 21,
    toDay: 30,
    labelKey: "seasonalTheme.lastTenEyebrow",
  },
  { id: "eidFitr", hijriMonth: 10, fromDay: 1, toDay: 3, labelKey: "eid.section.fitr" },
  { id: "hajj", hijriMonth: 12, fromDay: 1, toDay: 9, labelKey: "seasonalTheme.hajjEyebrow" },
  { id: "eidAdha", hijriMonth: 12, fromDay: 10, toDay: 13, labelKey: "eid.section.adha" },
];

export function isAppIconId(value: unknown): value is AppIconId {
  return typeof value === "string" && (APP_ICON_IDS as readonly string[]).includes(value);
}

export function isAppIconPreference(value: unknown): value is AppIconPreference {
  return value === "seasonal" || value === "classic" || isAppIconId(value);
}

export function appIconSeason(id: AppIconId): AppIconSeason {
  const season = APP_ICON_SEASONS.find((entry) => entry.id === id);
  if (!season) throw new Error(`Unknown app icon: ${id}`);
  return season;
}

/** i18n key naming a preference (picker label, settings summary). */
export function appIconPreferenceLabelKey(preference: AppIconPreference): string {
  if (preference === "seasonal") return "appIcon.mode.seasonal";
  if (preference === "classic") return "appIcon.mode.classic";
  return appIconSeason(preference).labelKey;
}

/** The seasonal icon for a Hijri month/day, or null outside every season. */
export function seasonalAppIconForHijri(month: number, day: number): AppIconId | null {
  const season = APP_ICON_SEASONS.find(
    (entry) => entry.hijriMonth === month && day >= entry.fromDay && day <= entry.toDay,
  );
  return season?.id ?? null;
}

export interface UpcomingAppIcon {
  id: AppIconId;
  /** Local midnight of the season's first day. */
  date: Date;
}

/**
 * Seasonal mode: the next seasonal icon to start after `from` (skipping the one
 * showing now), within `horizonDays` — a little over a Hijri year. Walks local days
 * on the same Hijri engine as {@link resolveAppIcon}, so it honours sighting and
 * manual day corrections.
 */
export function nextSeasonalAppIcon(
  from: Date = new Date(),
  timeZone?: string,
  horizonDays = 400,
): UpcomingAppIcon | null {
  let previous = resolveAppIcon("seasonal", from, timeZone);
  const day = new Date(from.getFullYear(), from.getMonth(), from.getDate(), 12);
  for (let i = 1; i <= horizonDays; i += 1) {
    day.setDate(day.getDate() + 1);
    const id = resolveAppIcon("seasonal", day, timeZone);
    if (id !== null && id !== previous) {
      return { id, date: new Date(day.getFullYear(), day.getMonth(), day.getDate()) };
    }
    previous = id;
  }
  return null;
}

/**
 * The icon this device should show (null = the classic primary icon). Seasonal
 * mode reads the same Hijri date as the home hero and seasonal banner — the
 * user's sighting location / Umm al-Qura choice and manual day corrections.
 */
export function resolveAppIcon(
  preference: AppIconPreference,
  date: Date = new Date(),
  timeZone?: string,
): AppIconId | null {
  if (preference === "classic") return null;
  if (preference !== "seasonal") return preference;
  const hijri = gregorianToHijri(date, timeZone);
  return seasonalAppIconForHijri(hijri.month, hijri.day);
}
